-- ============================================================
-- 005: 서울 구 경계(seoul_gu) + 코스 지역(routes.region) 채우기
--
-- 코스 저장 시 지역을 카카오 API 로 찾았는데, 키가 없으면 조회가 실패해서
-- 기존 코스의 region 이 전부 비어 있었다. 이제 백엔드(RegionService)가
-- "출발점이 들어 있는 구 경계"로 지역을 정하므로, 그 경계 데이터를 넣고
-- 기존 코스도 같은 규칙으로 채운다.
--
-- 경계 데이터 출처: southkorea/seoul-maps (Apache-2.0)
--   juso/2015/json/seoul_municipalities_geo.json — 원본은 통계청 센서스용 행정구역경계
--   좌표는 소수점 6자리(약 0.1m)로 반올림해 넣었다. 원본 경계 일부(강서구)가 스스로 교차하는
--   도형이라 ST_MakeValid 로 고쳐서 넣는다(안 고치면 ST_Covers 판정이 틀리거나 오류가 날 수 있다).
--
-- 규칙 (RegionService 와 동일 — 한쪽을 바꾸면 같이 바꾼다)
--   - 출발점이 어느 구 경계에도 없으면(서울 밖) 비워 둔다
--   - 이미 지역이 있는 코스는 건드리지 않는다 → 여러 번 실행해도 안전
-- ============================================================

-- 1. 구 경계 테이블 (JPA 엔티티 없음 — RegionService 가 SQL 로만 읽는다)
CREATE TABLE IF NOT EXISTS seoul_gu (
    code VARCHAR(5) PRIMARY KEY,               -- 시군구 코드 (SIG_CD)
    name VARCHAR(20) NOT NULL,                 -- 구 이름 (SIG_KOR_NM) — 프론트 GU_LIST 와 같은 표기
    geom geometry(MultiPolygon, 4326) NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_seoul_gu_geom ON seoul_gu USING GIST (geom);

